1	import Foundation
2	import Network
3	@testable import ReachyKit
4	import Testing
5	
6	@Suite("SetTargetClient")
7	struct SetTargetClientTests {
8	    @Test("wire format matches FullBodyTarget: snake_case keys, flat XYZRPY head pose")
9	    func wireFormat() throws {
10	        let target = SetTargetClient.Target(
11	            z: 0.01, pitch: 0.2, yaw: -0.3, bodyYaw: 0.5, antennaLeft: 0.1, antennaRight: -0.1
12	        )
13	        let json = try JSONSerialization.jsonObject(with: SetTargetClient.encode(target)) as? [String: Any]
14	        let head = json?["target_head_pose"] as? [String: Double]
15	        #expect(head?["pitch"] == 0.2)
16	        #expect(head?["yaw"] == -0.3)
17	        #expect(head?["z"] == 0.01)
18	        #expect(json?["target_body_yaw"] as? Double == 0.5)
19	        #expect(json?["target_antennas"] as? [Double] == [0.1, -0.1])
20	    }
21	
22	    @Test("throttle: a burst of sends collapses to one wire frame", .timeLimit(.minutes(1)))
23	    func throttle() async throws {
24	        let received = ReceivedCounter()
25	        let accepted = ReceivedCounter()
26	        let server = try LocalWebSocketServer { connection in
27	            accepted.increment()
28	            receiveLoop(connection, counter: received)
29	        }
30	        defer { server.stop() }
31	        let port = try await server.readyPort()
32	
33	        let client = try SetTargetClient(
34	            address: RobotAddress(host: "127.0.0.1", port: Int(port)),
35	            minSendInterval: .seconds(10)
36	        )
37	        await client.connect()
38	        // `connect()` returns before the handshake, so wait on the server actually
39	        // accepting rather than on a duration a loaded CI runner can overrun.
40	        await waitUntil(accepted.count >= 1)
41	
42	        for i in 0 ..< 5 {
43	            await client.send(.init(bodyYaw: Double(i)))
44	        }
45	        // The 10 s throttle means no second frame can follow, so the first arrival
46	        // is already the final count.
47	        await waitUntil(received.count >= 1)
48	        #expect(received.count == 1)
49	        await client.disconnect()
50	    }
51	
52	    private func waitUntil(
53	        _ condition: @autoclosure () -> Bool,
54	        timeout: Duration = .seconds(10)
55	    ) async {
56	        let start = ContinuousClock.now
57	        while !condition(), start.duration(to: .now) < timeout {
58	            try? await Task.sleep(for: .milliseconds(10))
59	        }
60	    }
61	}
62	
63	private final class ReceivedCounter: @unchecked Sendable {
64	    private let lock = NSLock()
65	    private var value = 0
66	    var count: Int {
67	        lock.withLock { value }
68	    }
69	
70	    func increment() {
71	        lock.withLock { value += 1 }
72	    }
73	}
74	
75	private func receiveLoop(_ connection: NWConnection, counter: ReceivedCounter) {
76	    connection.receiveMessage { data, _, _, error in
77	        if data != nil {
78	            counter.increment()
79	        }
80	        if error == nil {
81	            receiveLoop(connection, counter: counter)
82	        }
83	    }
84	}
